import { pointInPolygon } from './pointInPolygon';

export interface ResolvedAddress {
  province: string;
  city: string;
  barangay: string;
}

interface BoundaryEntry {
  p: string;
  c: string;
  b: string;
  bbox: [number, number, number, number]; // west, south, east, north
  rings: number[][];
}

let entries: BoundaryEntry[] | null = null;

// The bundle is ~866 KB of polygons generated by
// scripts/build-barangay-boundaries.js from faeldon/philippines-json-maps
// (MIT, PSGC 2023). Required lazily so app start never parses it; Metro
// executes a module on its first require.
function loadEntries(): BoundaryEntry[] {
  if (entries) return entries;
  try {
    entries = require('../../data/mimaropaBoundaries.json') as BoundaryEntry[];
  } catch (err) {
    console.warn('[resolveAddress] boundary bundle unavailable', err);
    entries = [];
  }
  return entries;
}

let warnedOnScanFailure = false;

// The Province / City / Barangay the pin sits in — exactly the strings the
// address dropdowns offer, so callers assign them straight into form state.
// Smallest-bbox-area match wins, not first hit: a barangay whose simplified
// polygon sits entirely inside a neighbour's simplified polygon would
// otherwise be unreachable by any coordinate, because the neighbour always
// matches first and never loses. That's not hypothetical — Tagwak (Boac,
// Marinduque) lies wholly inside Pawa's polygon, and "Pawa" sorts first
// alphabetically, so under first-hit no point on Earth could ever resolve
// to Tagwak. Smallest-bbox-area prefers the more specific (smaller) match
// among overlapping hits, at a small extra cost (scanning every entry
// instead of stopping at the first hit).
export function resolveAddress(lat: number, lng: number): ResolvedAddress | null {
  try {
    let best: BoundaryEntry | null = null;
    let bestArea = Infinity;
    for (const e of loadEntries()) {
      const [w, s, east, n] = e.bbox;
      if (lng < w || lng > east || lat < s || lat > n) continue;
      if (!pointInPolygon(lng, lat, e.rings)) continue;
      const area = (east - w) * (n - s);
      if (area < bestArea) {
        bestArea = area;
        best = e;
      }
    }
    return best ? { province: best.p, city: best.c, barangay: best.b } : null;
  } catch (err) {
    if (!warnedOnScanFailure) {
      warnedOnScanFailure = true;
      console.warn('[resolveAddress] boundary scan failed', err);
    }
    return null;
  }
}

export function formatResolvedAddress(address: ResolvedAddress | null): string {
  if (!address) return 'Outside MIMAROPA barangay boundaries';
  return `Brgy. ${address.barangay}, ${address.city}, ${address.province}`;
}
